                ModifierOption("qe_gai_agil", "Ágil", 1, "É imune à Lentidão (efeitos comuns/perícia), recebe R+3 contra Lentidão (Poder/Vantagem). H+1 para testes de corrida e definir velocidade."),
                ModifierOption("qe_gai_anaerobico", "Anaeróbico", 1, "Não precisa respirar, tornando-se imune a efeitos de asfixia e toxinas aéreas."),
