                ModifierOption("qe_gai_controle_digest", "Controle Digestivo", 1, "R+2 contra venenos. Pode armazenar pequenos itens no estômago (engolindo/regurgitando à vontade)."),
                ModifierOption("qe_gai_corpo_ferro", "Corpo de Ferro", 1, "Consegue +3 em uma FD e um sucesso automático em um teste de A por sessão, além de +1 em testes de A."),
                ModifierOption("qe_gai_clareza", "Clareza", 1, "Imune à Confusão comum/perícia, R+3 contra Confusão de Poder/Vantagem. R+1 contra efeitos mentais."),
                ModifierOption("qe_gai_coracao_pedra", "Coração de Pedra", 1, "Imune à Afeição comum/perícia, R+3 contra Afeição de Poder/Vantagem. Por 1PM pode fornecer a aliado Junto."),
                ModifierOption("qe_gai_criptobiose", "Criptobiose", 1, "Por 1PM pausa o metabolismo: ignora STNs ou estabiliza Teste de Morte. Fica indefeso/inconsciente até acordar."),
                ModifierOption("qe_gai_deslizar", "Deslizar", 1, "Move-se deslizando em velocidade de corrida sem cansar. +2 em Mov., 1 sucesso em teste de Mov. e uma esquiva por sessão."),
