                ModifierOption("qe_gai_equilibrio", "Equilíbrio", 1, "Nunca cai. Aterrissa de pé ignorando 1d de dano, não gasta mov. para levantar. Imune a escorregadio."),
                ModifierOption("qe_gai_erro_prudente", "Erro Prudente", 1, "Após uma falha, teste R. Se passar recupere 1PV ou 1PM."),
                ModifierOption("qe_gai_escavacao", "Escavação", 1, "Move-se através de solo sólido na velocidade normal, criando túnel (aberto ou colapsa)."),
                ModifierOption("qe_gai_estomago_avestruz", "Estômago de Avestruz", 1, "Come qualquer coisa. R+2 contra doenças, imune a intoxicação/envenenamento por comida."),
                ModifierOption("qe_gai_flexivel", "Flexível", 1, "Passa por lugares estreitos sem testes e recebe 1d bônus para escapar de agarrões."),
                ModifierOption("qe_gai_foco", "Foco", 1, "Sem penalidades ambientais de concentração. Gasta 1PM para manter concentração ao receber dano."),
                ModifierOption("qe_gai_forca_extra", "Força Extra", 1, "FA+3 em ataque de F, +1 sucesso autom. em F/sessão, +1 testes de F."),
                ModifierOption("qe_gai_glutao", "Glutão", 1, "Recupera 5PV/PM por refeição. Pode usar uma Cena para comer e restaurar 2PV/PM, ou todos se houver fartura (-1d por estufado)."),
                ModifierOption("qe_gai_impulsividade", "Impulsividade", 1, "Iniciativa +3 e uma vez por sessão é o primeiro a agir sem rolar Iniciativa."),
                ModifierOption("qe_gai_longevidade", "Longevidade", 1, "Você não envelhece, sendo imune a efeitos de envelhecimento ou rejuvenescimento."),
                ModifierOption("qe_gai_mira", "Mira", 1, "FA+3 em ataque de PDF, +1 sucesso autom. em PDF/sessão, +1 testes de PDF."),
                ModifierOption("qe_gai_nado_anfibio", "Nado Anfíbio", 1, "Nado em velocidade máxima, como se fosse em terra firme."),
                ModifierOption("qe_gai_perseveranca", "Perseverança", 1, "Pode gastar 1PM para cancelar temporariamente um redutor de -1 por uma Cena."),
                ModifierOption("qe_gai_quase_voo", "Quase Voo", 1, "Move-se no ar com cordas/teias/saltos. Requer Ação para estabilizar, ou cairá."),
                ModifierOption("qe_gai_queda_segura", "Queda Segura", 1, "Cai de qualquer altura sem se ferir, desacelerando com superfícies."),
                ModifierOption("qe_gai_resiliencia", "Resiliência", 1, "Permanece consciente mesmo estando Inconsciente, Muito Ferido ou Quase Morto (sem agir)."),
                ModifierOption("qe_gai_robustez", "Robustez", 1, "Imune à Debilitação comum/perícia, R+3 contra de Poder/Vantagem. R+1 contra Dano Contínuo."),
                ModifierOption("qe_gai_sabe_tudo", "Sabe Tudo", 1, "1 sucesso autom. em conhecimento/sessão. Por 1PM relembra detalhes específicos."),
                ModifierOption("qe_gai_sem_dor", "Sem Dor", 1, "Resistente à dor, FD+1 e +2 contra testes de dor (tortura, etc)."),
                ModifierOption("qe_gai_sem_fome", "Sem Fome", 1, "Só precisa de água para viver."),
                ModifierOption("qe_gai_sem_rastros", "Sem Rastros", 1, "Não deixa pegadas na neve/areia (ainda detectado por sentidos)."),
                ModifierOption("qe_gai_sem_sede", "Sem Sede", 1, "Não sofre efeitos de inanição sem água."),
                ModifierOption("qe_gai_sem_sono", "Sem Sono", 1, "Não precisa dormir (ainda pode descansar se quiser)."),
                ModifierOption("qe_gai_sono_leve", "Sono Leve", 1, "Dorme superficialmente, rola testes como acordado, +3 contra Sono."),
                ModifierOption("qe_gai_sortudo", "Sortudo", 1, "1x/dia rolar novamente um teste, ou rolagem positiva de aleatoriedade."),
                ModifierOption("qe_gai_viagem_espacial", "Viagem Espacial", 1, "Viaja rapidamente no vácuo e imune a seus efeitos.")
            )
        ))
        list.add(ItemDefinition(name = "RECURSOS", cost = "1-3", description = "Você tem acesso a uma fonte de apoio excepcional, seja ela oriunda de um patrono poderoso, riqueza, influência ou status elevado. No entanto, esses recursos não são infinitos e devem ser usados com sabedoria.\n\n1PT Pode invocar seus recursos uma vez por sessão sem custo em PM. (1PM) A forma da ajuda é determinada pelo Mestre, podendo incluir desde suprimentos básicos até uma chance de influenciar um evento importante. Subornos: Uma oportunidade de negociar com um NPC hostil. Apoio: Contratar mercenários ou aliados temporários. EQPs ou Consumíveis: Fornecimento de itens úteis para a missão. A ajuda invocada dura uma Cena (Cena) e desaparece após o uso, seja quebrando, evaporando ou finalizando contratos. Se o recurso invocado representar uma Vantagem, o valor máximo é de 1PT.\n\n2PT Você pode ser um policial ou agente do governo, com todos os poderes legais que isso acarreta. Pode portar armas, acessar informações confidenciais, invadir locais restritos e prender ou eliminar pessoas sem grandes repercussões. (2PM) Antes de sair para uma missão, pode adquirir um Item Consumível (geralmente de cura) que dura enquanto a missão durar. (2PM) Possui à disposição itens essenciais para suas missões (uma mochila ou bolsa de parafernálias). Recebe ou pode fornecer a um aliado +2 em testes de Perícia. (2PM) Seu recurso pode representar até 2PT de Vantagens.\n\n3PT Você é uma pessoa de prestígio, como um diplomata, príncipe ou embaixador, fora da maior parte dos sistemas legais. (3PM) Antes de iniciar uma missão, pode adquirir um item ou equipamento útil relacionado ao contexto da missão (como uma arma específica contra monstros ou ferramentas para infiltração). (3PM) Seu recurso pode representar até 3PT de Vantagens.\n\n"))
        list.add(ItemDefinition(name = "REGENERAÇÃO", cost = "1-3", description = "Você possui um fator de cura excepcional, tornando-se extremamente difícil de eliminar. Seu corpo se recupera rapidamente de ferimentos graves e até mesmo da morte, em algumas circunstâncias.\n\n1PT Recupera sua R em PV por Cena. Seu descanso é sempre pleno.\n\n2PT Regenera 1PV cada dois turnos em combate (use um dado e escolha par ou ímpar para marcar o turno em que você regenera, ou uma moeda e escolha um dos lados), a regeneração começa no seu segundo turno de combate. Recupera Rx2PV por Cena. Qualquer descanso recupera todo seu PV.\n\n3PT Regenera 1PV por turno em combate e Rx3PV por Cena.\n\n"))
        list.add(ItemDefinition(name = "RESISTÊNCIA ESPECIAL", cost = "1-2", description = "Você possui uma resistência superior contra um tipo específico de ataque ou poder, tornando-se mais difícil de ser afetado por ele.\n\n1PT Recebe +3 numa categoria de ataque que exija R. Escolha uma categoria:\n\nStatus Negativo: Inclui todos os efeitos de status.\n\nPoder: Escolha um tipo específico, como Magia ou Ki.\n\nVantagens: Abrange todas as vantagens que exijam testes para ressitir.\n\n2PT Recebe 1d bônus ao testar R contra o tipo de ataque escolhido. (2PM) Escolha um ataque específico dentro da categoria de sua resistência (como uma única Vantagem, ou um único Status Negativo), você pode ignorar completamente o efeito.\n\n"))
        list.add(ItemDefinition(name = "RESTAURAÇÃO", cost = "1", description = "Você pode curar uma ou diversas condições que põem a vida do alvo em risco.\n\nAo comprar Restauração escolha um dos seguintes Status Negativo: Afeição, Asfixiar, Atordoar, Confusão, Dano Contínuo, Debilitar, Desnutrição, Lentidão, Paralisia, Medo ou Sono. Cada Status Negativo custa 1PT para compra, 1PM para cura e toma uma Ação.\n\nVocê pode optar por curar Máculas ao invés de STNs. O personagem pode curar efeitos de Mácula com custo total em PT igual ou inferior ao valor investido em Restauração de Mácula. Cada efeito curado custa 1PM por PT da Mácula removida, e toma uma Ação.\n\nEm uma única Ação, você pode curar até 3 efeitos simultaneamente, sejam Status Negativo ou máculas ao custo de +1PM por efeito adicional curado.\n\nVocê pode curar alvos adicionais ao mesmo tempo, gastando 1PM extra por alvo além do primeiro.\n\n"))
        list.add(ItemDefinition(
            name = "SENTIDOS ESPECIAIS", 
            cost = "1-3", 
            description = "Seus sentidos são mais aguçados que o normal. Quando possuem alcance, funcionam automaticamente em Perto, mas exigem testes em Longe. Sempre que possível, um sentido indica a direção e distância aproximada do alvo detectado, respeitando suas limitações naturais.\n\nSe exposto a uma fonte intensa do próprio sentido — como um som extremamente agudo para Audição Aguçada ou uma grande concentração de energia para Detectar Energia — o usuário fica atordoado enquanto estiver Perto e por 1 turno após se afastar.\n\nPara cada PT você escolhe três sentidos. Eles ampliam muito sua percepção sobre o ambiente.",
            isModular = true,
            baseCostPt = 0,
            modifiers = listOf(
                ModifierOption("se_gai_audicao", "Audição Aguçada", 1, "Capta sons baixos, distantes ou em frequências inaudíveis para humanos."),
                ModifierOption("se_gai_det_criatura", "Detectar Criatura", 1, "Escolha uma espécie de ser vivo. Você sente sua presença quando está próxima."),
                ModifierOption("se_gai_det_energia", "Detectar Energia", 1, "Percebe um tipo específico de energia de Poder (ex.: ki, cosmo, nen)."),
                ModifierOption("se_gai_det_mentira", "Detectar Mentiras", 1, "Ao custo de 1PM por frase, percebe se alguém está mentindo."),
                ModifierOption("se_gai_det_objeto", "Detectar Objeto", 1, "Escolha um tipo de objeto (ex.: armas) ou um material (ex.: ouro). Você pode detectar sua presença."),
                ModifierOption("se_gai_infravisao", "Infravisão", 1, "Enxerga calor e encontra facilmente criaturas de sangue quente no escuro."),
                ModifierOption("se_gai_olfato", "Olfato Aguçado", 1, "Fareja como um cão perdigueiro."),
