                ModifierOption("se_gai_radio", "Rádio", 1, "\"Ouve\" frequências de rádio (AM, FM, celular, internet) e pode transmiti-las."),
                ModifierOption("se_gai_direcao", "Senso de Direção", 1, "Sempre sabe onde é o norte, retorna por qualquer caminho, facilita sair de labirintos."),
