                ModifierOption("se_gai_indole", "Sentir Índole", 1, "Por 1PM, percebe se criatura possui boas, más ou neutras intenções na Cena atual."),
                ModifierOption("se_gai_invisivel", "Ver o Invisível", 1, "Vê seres/objetos invisíveis. (Radar/Infravisão e outros Sentidos não o fazem)."),
                ModifierOption("se_gai_visao_aguc", "Visão Aguçada", 1, "Enxerga detalhes minuciosos à distância, como uma águia."),
